// Curated real webcam catalog — expanded 2026-09-17.
// 600 feeds across 85 countries. Every channelId was verified
// one-by-one against youtube.com: /live resolution (ytInitialPlayerResponse
// isLiveContent) with an RSS + oEmbed cross-check ladder for bot-walled
// channels, plus identity gates (city token in channel name / live title /
// discovery match) and a VLM thumbnail review. Rotator/aggregator channels,
// music/ambience impostors, pre-recorded loops and monitor screens are
// excluded; news-studio feeds are retained only with honest
// channel-attributed labels.

export type WebcamRegion =
  | 'middle-east'
  | 'africa'
  | 'europe'
  | 'asia'
  | 'americas'
  | 'oceania'
  | 'space';

export interface WebcamFeed {
  id: string;
  city: string;
  country: string;
  region: WebcamRegion;
  channelHandle: string;
  /** Stable YouTube channel id — the embed uses /embed/live_stream?channel= so
   *  YouTube resolves the channel's CURRENT live stream from the viewer's IP. */
  channelId: string;
}

